 @app.route('/alerts/webhook', methods=['POST'])
 def prometheus_webhook():
     from flask import request
     data = request.get_json() or {}
     alerts = data.get('alerts', [])

     for alert in alerts:
         if alert.get('status') == 'firing':
             summary = alert.get('annotations', {}).get('summary', 'Alert')
             description = alert.get('annotations', {}).get('description', '')
             message = f"🚨 {summary}\n{description}"
             agent.telegram_exporter.send(message)
         elif alert.get('status') == 'resolved':
             summary = alert.get('annotations', {}).get('summary', 'Alert')
             message = f"✅ Resolved: {summary}"
             agent.telegram_exporter.send(message)

     return jsonify({'received': len(alerts)})

